insert into pw_player_game(player_id,game_id,game_nickname,server_name,rank_name,experience_years,introduction,is_primary,audit_status,enabled) select p.id,g.id,'北极星Delta','国服','全面战场王牌',2,'主打大战场指挥与团队协作',true,'APPROVED',true from pw_player p cross join pw_game g where p.player_no='DEMO-PW-001' and g.game_code='delta-force' and not exists(select 1 from pw_player_game x where x.player_id=p.id and x.game_id=g.id);
insert into pw_player_game(player_id,game_id,game_nickname,server_name,rank_name,experience_years,introduction,is_primary,audit_status,enabled) select p.id,g.id,'小熊冲锋','国服','烽火地带钻石',1,'熟悉物资点与撤离路线',true,'APPROVED',true from pw_player p cross join pw_game g where p.player_no='DEMO-PW-002' and g.game_code='delta-force' and not exists(select 1 from pw_player_game x where x.player_id=p.id and x.game_id=g.id);
