insert into pw_player_game(player_id,game_id,game_nickname,server_name,rank_name,experience_years,introduction,is_primary,audit_status,enabled) select p.id,g.id,'CandyAim','国服','超凡',2,'娱乐匹配与决斗位',true,'APPROVED',true from pw_player p cross join pw_game g where p.player_no='DEMO-PW-004' and g.game_code='valorant' and not exists(select 1 from pw_player_game x where x.player_id=p.id and x.game_id=g.id);
insert into pw_player_game(player_id,game_id,game_nickname,server_name,rank_name,experience_years,introduction,is_primary,audit_status,enabled) select p.id,g.id,'GreyPigeon','国服','钻石',1,'待审核的双游资料',true,'PENDING',true from pw_player p cross join pw_game g where p.player_no='DEMO-PW-005' and g.game_code='delta-force' and not exists(select 1 from pw_player_game x where x.player_id=p.id and x.game_id=g.id);
insert into pw_player_game(player_id,game_id,game_nickname,server_name,rank_name,experience_years,introduction,is_primary,audit_status,enabled) select p.id,g.id,'GreyValorant','国服','铂金',1,'待审核的副游戏资料',false,'PENDING',true from pw_player p cross join pw_game g where p.player_no='DEMO-PW-005' and g.game_code='valorant' and not exists(select 1 from pw_player_game x where x.player_id=p.id and x.game_id=g.id);
insert into pw_player_tag_rel(player_id,tag_id) select p.id,t.id from pw_player p cross join pw_player_tag t where p.player_no='DEMO-PW-001' and t.tag_code in('good-command','aim-strong') and not exists(select 1 from pw_player_tag_rel x where x.player_id=p.id and x.tag_id=t.id);
insert into pw_player_tag_rel(player_id,tag_id) select p.id,t.id from pw_player p cross join pw_player_tag t where p.player_no='DEMO-PW-002' and t.tag_code in('patient','funny') and not exists(select 1 from pw_player_tag_rel x where x.player_id=p.id and x.tag_id=t.id);
insert into pw_player_tag_rel(player_id,tag_id) select p.id,t.id from pw_player p cross join pw_player_tag t where p.player_no='DEMO-PW-003' and t.tag_code in('aim-strong','good-command','late-night') and not exists(select 1 from pw_player_tag_rel x where x.player_id=p.id and x.tag_id=t.id);
insert into pw_player_tag_rel(player_id,tag_id) select p.id,t.id from pw_player p cross join pw_player_tag t where p.player_no='DEMO-PW-004' and t.tag_code in('funny','late-night') and not exists(select 1 from pw_player_tag_rel x where x.player_id=p.id and x.tag_id=t.id);
insert into pw_player_game_position(player_game_id,position_id,is_primary) select pg.id,pos.id,true from pw_player_game pg join pw_player p on p.id=pg.player_id join pw_game_position pos on pos.game_id=pg.game_id where p.player_no='DEMO-PW-001' and pos.position_code='warfare' and not exists(select 1 from pw_player_game_position x where x.player_game_id=pg.id and x.position_id=pos.id);
insert into pw_player_game_position(player_game_id,position_id,is_primary) select pg.id,pos.id,false from pw_player_game pg join pw_player p on p.id=pg.player_id join pw_game_position pos on pos.game_id=pg.game_id where p.player_no='DEMO-PW-001' and pos.position_code='assault' and not exists(select 1 from pw_player_game_position x where x.player_game_id=pg.id and x.position_id=pos.id);
insert into pw_player_game_position(player_game_id,position_id,is_primary) select pg.id,pos.id,true from pw_player_game pg join pw_player p on p.id=pg.player_id join pw_game_position pos on pos.game_id=pg.game_id where p.player_no='DEMO-PW-002' and pos.position_code='operator' and not exists(select 1 from pw_player_game_position x where x.player_game_id=pg.id and x.position_id=pos.id);
insert into pw_player_game_position(player_game_id,position_id,is_primary) select pg.id,pos.id,true from pw_player_game pg join pw_player p on p.id=pg.player_id join pw_game_position pos on pos.game_id=pg.game_id where p.player_no='DEMO-PW-003' and pos.position_code='controller' and not exists(select 1 from pw_player_game_position x where x.player_game_id=pg.id and x.position_id=pos.id);
insert into pw_player_game_position(player_game_id,position_id,is_primary) select pg.id,pos.id,false from pw_player_game pg join pw_player p on p.id=pg.player_id join pw_game_position pos on pos.game_id=pg.game_id where p.player_no='DEMO-PW-003' and pos.position_code='initiator' and not exists(select 1 from pw_player_game_position x where x.player_game_id=pg.id and x.position_id=pos.id);
insert into pw_player_game_position(player_game_id,position_id,is_primary) select pg.id,pos.id,true from pw_player_game pg join pw_player p on p.id=pg.player_id join pw_game_position pos on pos.game_id=pg.game_id where p.player_no='DEMO-PW-004' and pos.position_code='duelist' and not exists(select 1 from pw_player_game_position x where x.player_game_id=pg.id and x.position_id=pos.id);
